class vDuVersionNotSupported(Exception):
    """ Raises when provided CU version is not supported. """

    def __init__(self, failed_vdu_version):
        super(vDuVersionNotSupported, self).__init__()
        self.failed_vdu = failed_vdu_version

    def __repr__(self):
        return f'Version {self.failed_vdu} of cu is not supported'
